const DownloadPage = () => {
  const [platform, setPlatform] = useState<Platform>('desktop');

  useEffect(() => {
    const userAgent = navigator.userAgent.toLowerCase();
    
    if (/iphone|ipad|ipod/.test(userAgent)) {
      setPlatform('ios');
    } else if (/android/.test(userAgent)) {
      setPlatform('android');
    } else {
      setPlatform('desktop');
    }
  }, []);

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary/5 via-background to-primary/10 flex flex-col items-center justify-center px-6 py-12">
      <SEOHead
        title="Télécharger l'application"
        description="Téléchargez l'application LaZone pour iOS et Android. L'immobilier en Afrique, simplifié."
        canonical="/download"
      />
      {/* Logo */}
      <div className="mb-8">
        <img 
          src={logoLazone} 
          alt="LaZone" 
          className="w-24 h-24 object-contain"
        />
      </div>

      {/* Title */}
      <h1 className="text-2xl md:text-3xl font-bold text-foreground text-center mb-4">
        Télécharger l'application LaZone
      </h1>

      {/* Subtitle */}
      <p className="text-muted-foreground text-center mb-10 max-w-sm">
        L'immobilier en Afrique, simplifié.
      </p>

      {/* Buttons */}
      <div className="flex flex-col gap-5 w-full max-w-xs items-center">
        {/* App Store Button - Show on iOS or Desktop */}
        {(platform === 'ios' || platform === 'desktop') && (
          <a
            href={APP_STORE_URL}
            target="_blank"
            rel="noopener noreferrer"
            className="transition-all hover:scale-[1.03] active:scale-[0.98]"
            aria-label="Télécharger sur l'App Store"
          >
            <AppStoreBadge />
          </a>
        )}

        {/* Google Play Button - Show on Android or Desktop */}
        {(platform === 'android' || platform === 'desktop') && (
          <a
            href={PLAY_STORE_URL}
            target="_blank"
            rel="noopener noreferrer"
            className="transition-all hover:scale-[1.03] active:scale-[0.98]"
            aria-label="Télécharger sur Google Play"
          >
            <GooglePlayBadge />
          </a>
        )}
      </div>

      {/* Footer note */}
      <p className="text-xs text-muted-foreground/60 mt-12 text-center">
        © {new Date().getFullYear()} LaZone
      </p>
    </div>
  );
};

export default DownloadPage;
